# ===================================================================
# BR-41: check_bedrock_central_guardrail_enforcement
# ===================================================================
class TestBR10CentralGuardrailBindings:
    """The central leg of BR-10 reads what binds invocation in one Region."""

    ARN = "arn:aws:bedrock:us-east-1:123456789012:guardrail/central01"

    @staticmethod
    def _deny(resource="*"):
        return json.dumps(
            {
                "Statement": [
                    {
                        "Sid": "Require",
                        "Effect": "Deny",
                        "Action": _INVOKE_BOTH,
                        "Resource": resource,
                        "Condition": {
                            "StringNotEquals": {
                                "bedrock:GuardrailIdentifier": (
                                    TestBR10CentralGuardrailBindings.ARN + ":2"
                                )
                            }
                        },
                    }
                ]
            }
        )

    def _read(
        self,
        configs=(),
        effective=None,
        scps=None,
        management=False,
        list_error=None,
        in_use=True,
    ):
        bedrock = MagicMock()
        if list_error is not None:
            bedrock.get_paginator.side_effect = list_error
        else:
            bedrock.get_paginator.return_value.paginate.return_value = [
                {"guardrailsConfig": list(configs)}
            ]
        org = MagicMock()
        if effective is None:
            org.describe_effective_policy.side_effect = ClientError(
                {"Error": {"Code": "EffectivePolicyNotFoundException"}},
                "DescribeEffectivePolicy",
            )
        else:
            org.describe_effective_policy.return_value = {
                "EffectivePolicy": {"PolicyContent": json.dumps(effective)}
            }
        inventory = {
            "items": [
                {"name": f"Scp{i}", "id": f"p-{i}", "content": content}
                for i, content in enumerate(scps or [])
            ],
            "errors": [],
            "list_error": "",
            "detached": [],
            "account": "123456789012",
            "path": [],
            "management_account": management,
        }
        with (
            patch(
                "bedrock_app.boto3.client",
                side_effect=lambda service, **_: {
                    "bedrock": bedrock,
                    "organizations": org,
                }[service],
            ),
            patch(
                "bedrock_app._organization_policy_context",
                return_value={"in_use": in_use},
            ),
        ):
            return bedrock_app._central_guardrail_bindings("us-east-1", inventory)

    def test_an_account_config_scoped_to_all_models_binds(self):
        good = {
            "configId": "all",
            "guardrailArn": self.ARN,
            "guardrailVersion": "2",
            "modelEnforcement": {"includedModels": ["ALL"], "excludedModels": []},
        }
        narrow = dict(
            good,
            configId="one",
            modelEnforcement={"includedModels": ["m1"], "excludedModels": []},
        )
        both = self._read(configs=[narrow, good])
        only_narrow = self._read(configs=[narrow])

        assert [values for _, values in both["mechanisms"]] == [[self.ARN + ":2"]]
        assert "configuration all" in both["mechanisms"][0][0]
        assert only_narrow["mechanisms"] == []

    def test_the_effective_policy_binds_only_its_region(self):
        def document(region):
            return {
                "bedrock": {
                    "guardrail_inference": {
                        region: {"c1": {"identifier": self.ARN + ":2"}}
                    }
                }
            }

        here = self._read(effective=document("us-east-1"))
        elsewhere = self._read(effective=document("eu-west-1"))

        assert [values for _, values in here["mechanisms"]] == [[self.ARN + ":2"]]
        assert elsewhere["mechanisms"] == []

    def test_an_scp_binds_in_a_member_account_only(self):
        member = self._read(scps=[self._deny()])
        management = self._read(scps=[self._deny()], management=True)
        foundation_only = self._read(
            scps=[self._deny("arn:aws:bedrock:*::foundation-model/*")]
        )

        assert [values for _, values in member["mechanisms"]] == [[self.ARN + ":2"]]
        assert "service control policy 'Scp0'" in member["mechanisms"][0][0]
        assert management["mechanisms"] == []
        assert foundation_only["mechanisms"] == []

    def test_an_unreadable_account_config_is_reported_unread(self):
        observed = self._read(
            list_error=ClientError(
                {"Error": {"Code": "AccessDeniedException", "Message": "no"}},
                "ListEnforcedGuardrailsConfiguration",
            )
        )

        assert observed["mechanisms"] == []
        assert len(observed["unread"]) == 1
        assert "account-enforced guardrail configurations" in observed["unread"][0]

    def test_no_organization_reads_the_account_leg_only(self):
        observed = self._read(in_use=False, scps=[self._deny()])

        assert observed == {"mechanisms": [], "unread": []}


class TestBR41CentralGuardrailEnforcement:
    """BR-41: Read the enforced guardrail version out of the policy document."""

    GUARDRAIL_ARN = "arn:aws:bedrock:us-east-1:123456789012:guardrail/abcd1234efgh"
    OTHER_GUARDRAIL_ARN = (
        "arn:aws:bedrock:us-east-1:123456789012:guardrail/zzzz9999yyyy"
    )

    # The documented Bedrock policy layout: a source policy wraps each value in
    # @@assign, and the effective policy Organizations computes carries the
    # plain value.
    @staticmethod
    def _bedrock_policy_document(
        guardrail_arn, guardrail_version, region="us-east-1", **extra
    ):
        config = {"identifier": {"@@assign": f"{guardrail_arn}:{guardrail_version}"}}
        config.update(extra)
        return {"bedrock": {"guardrail_inference": {region: {"config_1": config}}}}

    @staticmethod
    def _effective_policy_document(
        guardrail_arn, guardrail_version, region="us-east-1", **extra
    ):
        config = {"identifier": f"{guardrail_arn}:{guardrail_version}"}
        config.update(extra)
        return {"bedrock": {"guardrail_inference": {region: {"config_1": config}}}}

    @staticmethod
    def _deny_without_guardrail(operator, condition_value):
        return {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "RequireApprovedGuardrail",
                    "Effect": "Deny",
                    "Action": [
                        "bedrock:InvokeModel",
                        "bedrock:InvokeModelWithResponseStream",
                    ],
                    "Resource": "*",
                    "Condition": {
                        operator: {"bedrock:GuardrailIdentifier": condition_value}
                    },
                }
            ],
        }

    # A configuration whose includedModels names ALL, with no exclusion and both
    # content modes COMPREHENSIVE, is the only account-level shape that covers
    # every invocation.
    @staticmethod
    def _account_config(
        config_id,
        included=("ALL",),
        excluded=(),
        system="COMPREHENSIVE",
        messages="COMPREHENSIVE",
        version="3",
        guardrail_arn=None,
        omit_model_enforcement=False,
    ):
        config = {
            "configId": config_id,
            "guardrailArn": guardrail_arn
            or TestBR41CentralGuardrailEnforcement.GUARDRAIL_ARN,
            "guardrailVersion": version,
            "owner": "ACCOUNT",
            "selectiveContentGuarding": {"system": system, "messages": messages},
        }
        if not omit_model_enforcement:
            config["modelEnforcement"] = {
                "includedModels": list(included),
                "excludedModels": list(excluded),
            }
        return config

    def _client_factory(
        self,
        bedrock_policies,
        scps,
        targets,
        contents,
        account,
        account_configs,
        account_pages,
        account_error,
        effective=None,
        share_policy=None,
        list_policies_error=None,
    ):
        org_client = MagicMock()
        org_client.describe_organization.return_value = {
            "Organization": {"MasterAccountId": "123456789012"}
        }
        # The account sits directly under the root, so a policy attached to
        # r-abc123 or to the account applies and one on an OU does not.
        org_client.list_parents.return_value = {
            "Parents": [{"Id": "r-abc123", "Type": "ROOT"}]
        }
        if effective is None:
            org_client.describe_effective_policy.side_effect = ClientError(
                {"Error": {"Code": "EffectivePolicyNotFoundException"}},
                "DescribeEffectivePolicy",
            )
        else:
            org_client.describe_effective_policy.return_value = {
                "EffectivePolicy": {"PolicyContent": json.dumps(effective)}
            }

        def list_policies(**kwargs):
            if list_policies_error is not None:
                raise list_policies_error
            if kwargs.get("Filter") == "BEDROCK_POLICY":
                return {"Policies": list(bedrock_policies)}
            return {"Policies": list(scps)}

        org_client.list_policies.side_effect = list_policies
        org_client.list_targets_for_policy.side_effect = lambda **kwargs: {
            "Targets": targets.get(kwargs["PolicyId"], [])
        }
        org_client.describe_policy.side_effect = lambda **kwargs: {
            "Policy": {"Content": json.dumps(contents.get(kwargs["PolicyId"], {}))}
        }

        sts_client = MagicMock()
        sts_client.get_caller_identity.return_value = {"Account": account}

        bedrock_client = MagicMock()
        if account_error is not None:
            bedrock_client.get_paginator.side_effect = account_error
        else:
            bedrock_client.get_paginator.return_value.paginate.return_value = (
                account_pages
                if account_pages is not None
                else [{"guardrailsConfig": list(account_configs)}]
            )

        bedrock_client.get_resource_policy.return_value = {
            "resourcePolicy": json.dumps(
                share_policy
                if share_policy is not None
                else TestBR41CentralGuardrailEnforcement.ORG_SHARE_POLICY
            )
        }

        return (
            org_client,
            bedrock_client,
            lambda service, **kwargs: {
                "organizations": org_client,
                "sts": sts_client,
                "bedrock": bedrock_client,
            }[service],
        )

    ORG_SHARE_POLICY = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Effect": "Allow",
                "Principal": "*",
                "Action": ["bedrock:ApplyGuardrail", "bedrock:GetGuardrail"],
                "Resource": "*",
                "Condition": {"StringEquals": {"aws:PrincipalOrgID": "o-a1b2c3d4e5"}},
            }
        ],
    }

    ROOT_TARGET = [{"TargetId": "r-abc123", "Type": "ROOT"}]

    def _run_clients(
        self,
        bedrock_policies=(),
        scps=(),
        targets=None,
        contents=None,
        account="123456789012",
        account_configs=(),
        account_pages=None,
        account_error=None,
        effective=None,
        share_policy=None,
        list_policies_error=None,
    ):
        org_client, bedrock_client, factory = self._client_factory(
            bedrock_policies,
            scps,
            targets or {},
            contents or {},
            account,
            account_configs,
            account_pages,
            account_error,
            effective,
            share_policy,
            list_policies_error,
        )
        with patch("bedrock_app.boto3.client", side_effect=factory):
            result = bedrock_app.check_bedrock_central_guardrail_enforcement(
                region="Global", api_region="us-east-1"
            )
        return org_client, bedrock_client, extract_csv_data(result)

    def _run(self, **kwargs):
        org_client, _, findings = self._run_clients(**kwargs)
        return org_client, findings

    def test_br41_draft_version_fails_while_published_version_passes(self):
        org_client, findings = self._run(
            effective=self._effective_policy_document(self.GUARDRAIL_ARN, "3"),
            bedrock_policies=[
                {"Id": "p-published", "Name": "PublishedGuardrail"},
                {"Id": "p-draft", "Name": "DraftGuardrail"},
            ],
            targets={
                "p-published": [{"TargetId": "r-abc123", "Type": "ROOT"}],
                "p-draft": [{"TargetId": "ou-1234", "Type": "ORGANIZATIONAL_UNIT"}],
            },
            contents={
                "p-published": self._bedrock_policy_document(self.GUARDRAIL_ARN, "3"),
                "p-draft": self._bedrock_policy_document(
                    self.OTHER_GUARDRAIL_ARN, "DRAFT"
                ),
            },
        )

        failed = [f for f in findings if f["Status"] == "Failed"]
        passed = [f for f in findings if f["Status"] == "Passed"]

        assert len(failed) == 1
        assert failed[0]["Check_ID"] == "BR-41"
        assert "DraftGuardrail" in failed[0]["Finding_Details"]
        assert "p-draft" in failed[0]["Finding_Details"]
        assert "DRAFT guardrail version" in failed[0]["Finding_Details"]
        assert self.OTHER_GUARDRAIL_ARN in failed[0]["Finding_Details"]

        assert len(passed) == 1
        assert "PublishedGuardrail" in passed[0]["Finding_Details"]
        assert "ROOT r-abc123" in passed[0]["Finding_Details"]
        assert "version 3" in passed[0]["Finding_Details"]
        assert "aws:PrincipalOrgID" in passed[0]["Finding_Details"]
        # An enforcing Bedrock policy short-circuits the SCP fallback.
        assert all(
            call.kwargs.get("Filter") == "BEDROCK_POLICY"
            for call in org_client.list_policies.call_args_list
        )

