    @staticmethod
    def _scp_items(*statements, name="KeyGuard"):
        return {
            "items": [
                {
                    "name": name,
                    "id": "p-key",
                    "content": json.dumps(
                        {"Version": "2012-10-17", "Statement": list(statements)}
                    ),
                    "attached_to": ["r-root"],
                }
            ],
            "errors": [],
            "list_error": None,
        }

    @staticmethod
    def _deny(action, condition=None, sid="Guard"):
        statement = {"Sid": sid, "Effect": "Deny", "Action": action, "Resource": "*"}
        if condition:
            statement["Condition"] = condition
        return statement

    BEDROCK_SERVICE = {
        "StringEquals": {
            "iam:ServiceSpecificCredentialServiceName": "bedrock.amazonaws.com"
        }
    }

    def _prevention(self, inventory, cache=None):
        _, findings = self._run({}, inventory=inventory, cache=cache)
        return self._by_name(findings, self.PREVENTION_FINDING)

    @classmethod
    def _token_denies(cls):
        return [
            cls._deny(
                "bedrock:CallWithBearerToken",
                {"StringEquals": {"bedrock:BearerTokenType": "LONG_TERM"}},
                sid="Bedrock",
            ),
            cls._deny(
                "bedrock-mantle:CallWithBearerToken",
                {"StringEquals": {"bedrock-mantle:BearerTokenType": "LONG_TERM"}},
                sid="Mantle",
            ),
        ]

    @classmethod
    def _if_exists_cap(cls, sid="Cap"):
        return cls._deny(
            "iam:CreateServiceSpecificCredential",
            dict(
                cls.BEDROCK_SERVICE,
                NumericGreaterThanIfExists={
                    "iam:ServiceSpecificCredentialAgeDays": "90"
                },
            ),
            sid=sid,
        )

