class TestBR27ContextualGrounding:
    """BR-27: Verify guardrails enable contextual grounding checks."""

    @pytest.fixture(autouse=True)
    def _no_deployed_guardrails(self):
        with patch(
            "bedrock_app.get_guardrail_attachment_inventory",
            return_value={"attachments": [], "versions": {}, "errors": []},
        ):
            yield

    @patch("bedrock_app.boto3.client")
    def test_br27_no_guardrails_returns_na(self, mock_client):
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        bedrock_client = MagicMock()
        bedrock_client.list_guardrails.return_value = {"guardrails": []}
        mock_client.return_value = bedrock_client

        result = check(region="us-east-1")
        findings = extract_csv_data(result)
        assert findings[0]["Status"] == "N/A"
        assert findings[0]["Check_ID"] == "BR-27"

    @patch("bedrock_app.boto3.client")
    def test_br27_grounding_enabled_returns_passed(self, mock_client):
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        bedrock_client = MagicMock()
        bedrock_client.list_guardrails.return_value = {
            "guardrails": [{"id": "gr1", "name": "GroundedGuardrail"}]
        }
        bedrock_client.get_guardrail.return_value = {
            "guardrail": {
                "contextualGroundingPolicy": {
                    "filters": [
                        {
                            "type": "GROUNDING",
                            "threshold": 0.75,
                            "action": "BLOCK",
                            "enabled": True,
                        },
                        {
                            "type": "RELEVANCE",
                            "threshold": 0.75,
                            "action": "BLOCK",
                            "enabled": True,
                        },
                    ]
                }
            }
        }
        mock_client.return_value = bedrock_client

        result = check(region="us-east-1")
        findings = extract_csv_data(result)
        passed = [f for f in findings if f["Status"] == "Passed"]
        assert len(passed) >= 1
        assert passed[0]["Check_ID"] == "BR-27"

    @patch("bedrock_app.boto3.client")
    def test_br27_no_grounding_returns_failed(self, mock_client):
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        bedrock_client = MagicMock()
        bedrock_client.list_guardrails.return_value = {
            "guardrails": [{"id": "gr1", "name": "PlainGuardrail"}]
        }
        bedrock_client.get_guardrail.return_value = {
            "guardrail": {"contextualGroundingPolicy": {"filters": []}}
        }
        mock_client.return_value = bedrock_client

        result = check(region="us-east-1")
        findings = extract_csv_data(result)
        assert findings[0]["Status"] == "Failed"
        assert findings[0]["Check_ID"] == "BR-27"

    @staticmethod
    def _grounding_filters(grounding, relevance):
        filters = []
        if grounding is not None:
            filters.append(dict(grounding, type="GROUNDING", enabled=True))
        if relevance is not None:
            filters.append(dict(relevance, type="RELEVANCE", enabled=True))
        return {"guardrail": {"contextualGroundingPolicy": {"filters": filters}}}

    @patch("bedrock_app.boto3.client")
    def test_br27_reports_the_threshold_and_action_it_observed(self, mock_client):
        """AIR-BDR-GRD-09: both filter types must block inside the 0-0.99 range."""
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        bedrock_client = MagicMock()
        bedrock_client.list_guardrails.return_value = {
            "guardrails": [
                {"id": "gr1", "name": "BlockingBoth"},
                {"id": "gr2", "name": "DetectOnlyRelevance"},
                {"id": "gr3", "name": "GroundingOnly"},
                {"id": "gr4", "name": "ZeroThreshold"},
            ]
        }
        bedrock_client.get_guardrail.side_effect = [
            self._grounding_filters(
                {"threshold": 0.85, "action": "BLOCK"},
                {"threshold": 0.7, "action": "BLOCK"},
            ),
            self._grounding_filters(
                {"threshold": 0.85, "action": "BLOCK"},
                {"threshold": 0.7, "action": "NONE"},
            ),
            self._grounding_filters({"threshold": 0.85, "action": "BLOCK"}, None),
            self._grounding_filters(
                {"threshold": 0.0, "action": "BLOCK"},
                {"threshold": 0.7, "action": "BLOCK"},
            ),
        ]
        mock_client.return_value = bedrock_client

        findings = extract_csv_data(check(region="us-east-1"))
        by_status = {}
        for finding in findings:
            by_status.setdefault(finding["Status"], []).append(finding)

        passed = by_status["Passed"]
        assert len(passed) == 1
        assert (
            "1 guardrails block on both GROUNDING and RELEVANCE"
            in passed[0]["Finding_Details"]
        )

        failed_details = {finding["Finding_Details"] for finding in by_status["Failed"]}
        assert len(failed_details) == 3
        detect_only = next(d for d in failed_details if "DetectOnlyRelevance" in d)
        assert "does not block on RELEVANCE" in detect_only
        assert "RELEVANCE threshold=0.7 action=NONE" in detect_only
        grounding_only = next(d for d in failed_details if "GroundingOnly" in d)
        assert "does not block on RELEVANCE" in grounding_only
        zero_threshold = next(d for d in failed_details if "ZeroThreshold" in d)
        assert "does not block on GROUNDING" in zero_threshold
        assert "GROUNDING threshold=0.0 action=BLOCK" in zero_threshold
        for finding in findings:
            assert_finding_schema(finding)

    @patch("bedrock_app.boto3.client")
    def test_br27_omitted_action_is_read_as_block(self, mock_client):
        """action postdates the filter, so an omitted action still blocks."""
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        bedrock_client = MagicMock()
        bedrock_client.list_guardrails.return_value = {
            "guardrails": [{"id": "gr1", "name": "LegacyGuardrail"}]
        }
        bedrock_client.get_guardrail.return_value = self._grounding_filters(
            {"threshold": 0.8}, {"threshold": 0.8}
        )
        mock_client.return_value = bedrock_client

        findings = [
            f
            for f in extract_csv_data(check(region="us-east-1"))
            if f["Finding"] == "Guardrail Contextual Grounding Check"
        ]
        assert [f["Status"] for f in findings] == ["Passed"]

    def test_br27_schema_valid(self):
        check = bedrock_app.check_bedrock_guardrail_contextual_grounding
        with patch("bedrock_app.boto3.client") as mock_client:
            bedrock_client = MagicMock()
            bedrock_client.list_guardrails.return_value = {"guardrails": []}
            mock_client.return_value = bedrock_client
            result = check(region="us-east-1")

        for f in extract_csv_data(result):
            assert_finding_schema(f)


class TestDeployedGuardrailVersions:
    """
    BR-26, BR-27 and BR-34 judge each guardrail version an agent, flow node or
    account-enforced configuration applies, and read values, not presence.
    """

    @pytest.fixture(autouse=True)
    def _no_knowledge_bases(self):
        with patch(
            "bedrock_app.get_knowledge_base_screening_inventory",
            return_value=NO_KNOWLEDGE_BASES,
        ):
            yield

    REGION = "us-east-1"
    PREVENTIVE = {
        "type": "PROMPT_ATTACK",
        "inputEnabled": True,
        "inputAction": "BLOCK",
        "inputStrength": "HIGH",
    }
    GOOD_PII = {
        "piiEntities": [
            {"type": "EMAIL", "action": "ANONYMIZE"},
            {"type": "AWS_ACCESS_KEY", "action": "BLOCK"},
            {"type": "AWS_SECRET_KEY", "action": "BLOCK"},
            {"type": "PASSWORD", "action": "ANONYMIZE"},
        ],
        "regexes": [
            {"name": "api-key", "pattern": "key_[0-9a-f]{40}", "action": "BLOCK"}
        ],
    }

    @classmethod
    def _content(cls, filters, tier="STANDARD"):
        policy = {"filters": filters}
        if tier:
            policy["tier"] = {"tierName": tier}
        return {"contentPolicy": policy}

    @staticmethod
    def _grounding(grounding=0.8, relevance=0.8, reasoning=None):
        detail = {
            "contextualGroundingPolicy": {
                "filters": [
                    {"type": "GROUNDING", "threshold": grounding, "action": "BLOCK"},
                    {"type": "RELEVANCE", "threshold": relevance, "action": "BLOCK"},
                ]
            }
        }
        if reasoning:
            detail["automatedReasoningPolicy"] = reasoning
        return detail

    @staticmethod
    def _attachments(versions, errors=None):
        return {
            "attachments": [],
            "versions": {
                (identifier, version): {
                    "surfaces": surfaces,
                    "detail": detail,
                    "error": "" if detail is not None else "AccessDeniedException",
                }
                for (identifier, version), (surfaces, detail) in versions.items()
            },
            "errors": errors or [],
        }

    @staticmethod
    def _draft(detail, name="Draft"):
        return {
            "items": [{"summary": {"id": "gr-d", "name": name}, "detail": detail}],
            "errors": [],
            "list_error": None,
        }

    @staticmethod
    def _rows(result, name):
        return [f for f in extract_csv_data(result) if f["Finding"] == name]

    def _prompt_attack(self, draft, attachments):
        return bedrock_app.check_bedrock_guardrail_prompt_attack_filter(
            region=self.REGION,
            guardrail_inventory=draft,
            attachment_inventory=attachments,
        )

    def test_br34_classic_tier_fails_a_preventive_filter(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE], tier="CLASSIC")),
            self._attachments({}),
        )

        rows = self._rows(result, "Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in rows] == ["Failed"]
        assert "the content-filter tier is CLASSIC" in rows[0]["Finding_Details"]
        assert "no prompt-leakage detection" in rows[0]["Finding_Details"]

    def test_br34_unreported_tier_is_not_assumed(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE], tier=None)),
            self._attachments({}),
        )

        rows = self._rows(result, "Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in rows] == ["N/A"]
        assert (
            "did not report contentPolicy.tier.tierName" in rows[0]["Finding_Details"]
        )

    def test_br34_deployed_version_is_judged_apart_from_a_passing_draft(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE])),
            self._attachments(
                {
                    ("gr-d", "1"): (["agent 'support' version 3"], self._content([])),
                    ("gr-d", "2"): (
                        ["flow 'intake' DRAFT node 'answer'"],
                        self._content([self.PREVENTIVE]),
                    ),
                }
            ),
        )

        assert [
            row["Status"]
            for row in self._rows(result, "Guardrail Prompt Attack Filter")
        ] == ["Passed"]
        deployed = self._rows(result, "Deployed Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in deployed] == ["Failed", "Passed"]
        assert (
            "gr-d version 1 (applied by agent 'support' version 3)"
            in deployed[0]["Finding_Details"]
        )
        assert "no PROMPT_ATTACK filter is configured" in deployed[0]["Finding_Details"]
        assert "gr-d version 2" in deployed[1]["Finding_Details"]
        assert "version 1" not in deployed[1]["Finding_Details"]
        assert (
            bedrock_app.GUARDRAIL_DEPLOYMENT_CEILING in deployed[1]["Finding_Details"]
        )

    def test_br34_unread_deployed_version_blocks_a_clean_pass(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE])),
            self._attachments(
                {
                    ("gr-d", "1"): (
                        ["agent 'a' DRAFT"],
                        self._content([self.PREVENTIVE]),
                    ),
                    ("arn:aws:bedrock:us-east-1:999999999999:guardrail/x", "4"): (
                        ["account-enforced configuration c-1"],
                        None,
                    ),
                }
            ),
        )

        deployed = self._rows(result, "Deployed Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in deployed] == ["N/A"]
        assert "This is not reported as Passed" in deployed[0]["Finding_Details"]
        assert "guardrail/x version 4" in deployed[0]["Finding_Details"]

    def test_br34_unlisted_attachment_source_blocks_a_clean_pass(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE])),
            self._attachments(
                {
                    ("gr-d", "1"): (
                        ["agent 'a' DRAFT"],
                        self._content([self.PREVENTIVE]),
                    )
                },
                errors=[
                    "flows were not read with bedrock:ListFlows (AccessDeniedException)"
                ],
            ),
        )

        deployed = self._rows(result, "Deployed Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in deployed] == ["N/A"]
        assert "bedrock:ListFlows" in deployed[0]["Finding_Details"]

    def test_br34_no_attachment_is_na_and_names_the_ceiling(self):
        result = self._prompt_attack(
            self._draft(self._content([self.PREVENTIVE])), self._attachments({})
        )

        deployed = self._rows(result, "Deployed Guardrail Prompt Attack Filter")
        assert [row["Status"] for row in deployed] == ["N/A"]
        assert "guardContent" in deployed[0]["Finding_Details"]

    @staticmethod
    def _pii_client(details):
        client = MagicMock()
        client.list_guardrails.return_value = {
            "guardrails": [
                {"id": f"gr-{index}", "name": name}
                for index, name in enumerate(details)
            ]
        }
        client.get_guardrail.side_effect = [
            {"guardrail": {"sensitiveInformationPolicy": policy}}
            for policy in details.values()
        ]
        return client

    def _pii(self, details, attachments=None):
        with patch("bedrock_app.boto3.client", return_value=self._pii_client(details)):
            return bedrock_app.check_bedrock_guardrail_pii_filters(
                region=self.REGION,
                attachment_inventory=attachments or self._attachments({}),
            )

    def test_br26_detect_only_entities_fail(self):
        result = self._pii(
            {
                "DetectOnly": {
                    "piiEntities": [{"type": "EMAIL", "action": "NONE"}],
                    "regexes": [{"name": "k", "pattern": "k", "action": "NONE"}],
                }
            }
        )

        rows = self._rows(result, "Guardrail Sensitive Information Filter Check")
        assert [row["Status"] for row in rows] == ["Failed"]
        detail = rows[0]["Finding_Details"]
        assert "no PII entity or regex blocks or masks on the output" in detail
        assert "no PII entity or regex blocks or masks on the input" in detail
        assert "EMAIL, regex 'k' take no blocking or masking action" in detail

    def test_br26_output_disabled_fails_the_output_side_only(self):
        result = self._pii(
            {
                "InputOnly": {
                    "piiEntities": [
                        {"type": entity_type, "action": "BLOCK", "outputEnabled": False}
                        for entity_type in ("EMAIL",)
                        + bedrock_app.CREDENTIAL_PII_ENTITY_TYPES
                    ],
                    "regexes": [
                        {
                            "name": "k",
                            "pattern": "k",
                            "action": "BLOCK",
                            "outputEnabled": False,
                        }
                    ],
                }
            }
        )

        detail = self._rows(result, "Guardrail Sensitive Information Filter Check")[0][
            "Finding_Details"
        ]
        assert "blocks or masks on the output" in detail
        assert "on the input" not in detail

    def test_br26_side_action_overrides_the_legacy_action(self):
        result = self._pii(
            {
                "OutputNone": {
                    "piiEntities": [
                        {"type": "EMAIL", "action": "BLOCK", "outputAction": "NONE"}
                    ],
                    "regexes": [
                        {
                            "name": "k",
                            "pattern": "k",
                            "action": "BLOCK",
                            "outputAction": "NONE",
                        }
                    ],
                }
            }
        )

        rows = self._rows(result, "Guardrail Sensitive Information Filter Check")
        assert rows[0]["Status"] == "Failed"
        assert "blocks or masks on the output" in rows[0]["Finding_Details"]

    def test_br26_entities_without_a_secrets_regex_fail(self):
        result = self._pii(
            {
                "EntitiesOnly": {
                    "piiEntities": [{"type": "EMAIL", "action": "ANONYMIZE"}],
                    "regexes": [],
                }
            }
        )

        rows = self._rows(result, "Guardrail Sensitive Information Filter Check")
        assert rows[0]["Status"] == "Failed"
        assert "no custom regex blocks or masks secrets" in rows[0]["Finding_Details"]

    def test_br26_two_guardrails_reach_both_verdicts(self):
        result = self._pii(
            {
                "Good": self.GOOD_PII,
                "Weak": {"piiEntities": [{"type": "EMAIL", "action": "NONE"}]},
            }
        )

        rows = self._rows(result, "Guardrail Sensitive Information Filter Check")
        assert [row["Status"] for row in rows] == ["Failed", "Passed"]
        assert "'Weak'" in rows[0]["Finding_Details"]
        assert "(Good)" in rows[1]["Finding_Details"]
        assert "Weak" not in rows[1]["Finding_Details"]
        assert (
            bedrock_app.SENSITIVE_INFORMATION_TOOL_CEILING in rows[1]["Finding_Details"]
        )

    @pytest.mark.parametrize(
        "missing",
        ["AWS_ACCESS_KEY", "AWS_SECRET_KEY", "PASSWORD"],
    )
    def test_br26_a_missing_credential_entity_type_fails(self, missing):
        weak = {
            "piiEntities": [
                entity
                for entity in self.GOOD_PII["piiEntities"]
                if entity["type"] != missing
            ],
            "regexes": self.GOOD_PII["regexes"],
        }
        result = self._pii({"Good": self.GOOD_PII, "Weak": weak})

        rows = self._rows(result, "Guardrail Sensitive Information Filter Check")
        assert [row["Status"] for row in rows] == ["Failed", "Passed"]
        assert (
            f"the credential PII entity type(s) {missing} do not block or mask on the output"
            in rows[0]["Finding_Details"]
        )
        assert "on the input" in rows[0]["Finding_Details"]

    def test_br26_a_credential_type_that_only_detects_on_the_output_fails(self):
        weak = {
            "piiEntities": [
                dict(entity, outputAction="NONE")
                if entity["type"] == "PASSWORD"
                else entity
                for entity in self.GOOD_PII["piiEntities"]
            ],
            "regexes": self.GOOD_PII["regexes"],
        }
        rows = self._rows(
            self._pii({"Weak": weak}), "Guardrail Sensitive Information Filter Check"
        )
        assert [row["Status"] for row in rows] == ["Failed"]
        assert (
            "PASSWORD do not block or mask on the output" in rows[0]["Finding_Details"]
        )
        assert "on the input" not in rows[0]["Finding_Details"]

    def test_br26_a_deployed_version_without_credential_types_fails(self):
        result = self._pii(
            {"Good": self.GOOD_PII},
            self._attachments(
                {
                    ("gr-0", "1"): (
                        ["agent 'a' version 1"],
                        {
                            "sensitiveInformationPolicy": {
                                "piiEntities": [{"type": "EMAIL", "action": "BLOCK"}],
                                "regexes": self.GOOD_PII["regexes"],
                            }
                        },
                    ),
                    ("gr-0", "2"): (
                        ["agent 'a' version 2"],
                        {"sensitiveInformationPolicy": self.GOOD_PII},
                    ),
                }
            ),
        )
        deployed = self._rows(result, "Deployed Guardrail Sensitive Information Filter")
        assert [row["Status"] for row in deployed] == ["Failed", "Passed"]
        assert (
            "AWS_ACCESS_KEY, AWS_SECRET_KEY, PASSWORD" in deployed[0]["Finding_Details"]
        )
        assert "version 1" in deployed[0]["Finding_Details"]

    def test_br26_deployed_version_is_judged_apart_from_a_passing_draft(self):
        result = self._pii(
            {"Good": self.GOOD_PII},
            self._attachments(
                {
                    ("gr-0", "1"): (
                        ["agent 'a' version 1"],
                        {"sensitiveInformationPolicy": {"piiEntities": []}},
                    )
                }
            ),
        )

        deployed = self._rows(result, "Deployed Guardrail Sensitive Information Filter")
        assert [row["Status"] for row in deployed] == ["Failed"]
        assert "no sensitive-information filter" in deployed[0]["Finding_Details"]

    def test_br27_deployed_version_reports_automated_reasoning(self):
        with patch("bedrock_app.boto3.client") as client:
            client.return_value.list_guardrails.return_value = {"guardrails": []}
            result = bedrock_app.check_bedrock_guardrail_contextual_grounding(
                region=self.REGION,
                attachment_inventory=self._attachments(
                    {
                        ("gr-1", "2"): (
                            ["flow 'f' 1 node 'kb'"],
                            self._grounding(
                                reasoning={
                                    "policies": [
                                        "arn:aws:bedrock:us-east-1:1:automated-reasoning-policy/p"
                                    ],
                                    "confidenceThreshold": 0.9,
                                }
                            ),
                        ),
                        ("gr-1", "3"): (
                            ["agent 'a' DRAFT"],
                            self._grounding(relevance=0),
                        ),
                    }
                ),
            )

        deployed = self._rows(result, "Deployed Guardrail Contextual Grounding")
        assert [row["Status"] for row in deployed] == ["Failed", "Passed"]
        assert "does not block on RELEVANCE" in deployed[0]["Finding_Details"]
        assert (
            "No Automated Reasoning policy is attached."
            in deployed[0]["Finding_Details"]
        )
        assert (
            "automated-reasoning-policy/p at confidenceThreshold 0.9"
            in deployed[1]["Finding_Details"]
        )
        assert (
            bedrock_app.CONTEXTUAL_GROUNDING_CEILING in deployed[1]["Finding_Details"]
        )

    def test_attachment_inventory_reads_every_deployed_version(self):
        agent_client = MagicMock()
        agent_client.list_agents.side_effect = [
            {
                "agentSummaries": [
                    {
                        "agentId": "A1",
                        "agentName": "support",
                        "guardrailConfiguration": {
                            "guardrailIdentifier": "gr-1",
                            "guardrailVersion": "DRAFT",
                        },
                    }
                ],
                "nextToken": "t",
            },
            {"agentSummaries": [{"agentId": "A2", "agentName": "bare"}]},
        ]
        agent_client.list_agent_aliases.side_effect = lambda agentId, **_: {
            "agentAliasSummaries": [
                {"routingConfiguration": [{"agentVersion": "DRAFT"}]},
                {"routingConfiguration": [{"agentVersion": "2"}]},
            ]
            if agentId == "A1"
            else []
        }
        agent_client.get_agent_version.return_value = {
            "agentVersion": {
                "guardrailConfiguration": {
                    "guardrailIdentifier": "arn:aws:bedrock:us-west-2:123456789012:guardrail/gr-2",
                    "guardrailVersion": "5",
                }
            }
        }
        agent_client.list_flows.return_value = {
            "flowSummaries": [{"id": "F1", "name": "intake"}]
        }
        agent_client.get_flow.return_value = {"definition": {"nodes": []}}
        agent_client.list_flow_aliases.return_value = {
            "flowAliasSummaries": [{"routingConfiguration": [{"flowVersion": "1"}]}]
        }
        agent_client.get_flow_version.return_value = {
            "definition": {
                "nodes": [
                    {
                        "name": "kb",
                        "configuration": {
                            "knowledgeBase": {
                                "guardrailConfiguration": {
                                    "guardrailIdentifier": "gr-1",
                                    "guardrailVersion": "DRAFT",
                                }
                            }
                        },
                    }
                ]
            }
        }
        bedrock_clients = {}

        def client(service, region_name=None, **_):
            if service == "bedrock-agent":
                return agent_client
            if region_name not in bedrock_clients:
                bedrock_clients[region_name] = MagicMock()
                bedrock_clients[
                    region_name
                ].list_enforced_guardrails_configuration.side_effect = ClientError(
                    {"Error": {"Code": "AccessDeniedException", "Message": "x"}},
                    "ListEnforcedGuardrailsConfiguration",
                )
                bedrock_clients[region_name].get_guardrail.return_value = {
                    "guardrail": {"name": region_name}
                }
            return bedrock_clients[region_name]

        with patch("bedrock_app.boto3.client", side_effect=client):
            inventory = bedrock_app.get_guardrail_attachment_inventory(self.REGION)

        assert agent_client.list_agents.call_count == 2
        agent_client.get_agent_version.assert_called_once_with(
            agentId="A1", agentVersion="2"
        )
        agent_client.get_flow_version.assert_called_once_with(
            flowIdentifier="F1", flowVersion="1"
        )
        assert inventory["versions"][("gr-1", "DRAFT")]["surfaces"] == [
            "agent 'support' DRAFT",
            "flow 'intake' 1 node 'kb'",
        ]
        west = inventory["versions"][
            ("arn:aws:bedrock:us-west-2:123456789012:guardrail/gr-2", "5")
        ]
        assert west["detail"] == {"name": "us-west-2"}
        assert west["surfaces"] == ["agent 'support' version 2"]
        bedrock_clients["us-west-2"].get_guardrail.assert_called_once_with(
            guardrailIdentifier="arn:aws:bedrock:us-west-2:123456789012:guardrail/gr-2",
            guardrailVersion="5",
        )
        assert len(inventory["errors"]) == 1
        assert "bedrock:ListEnforcedGuardrailsConfiguration" in inventory["errors"][0]


class TestGuardrailInterventionLogging:
    """AIR-FND-DET-04: an intervention is an event only if invocation logging records it."""

    REGION = "us-east-1"

    def _run(self, config=None, error=None):
        client = MagicMock()
        if error is not None:
            client.get_model_invocation_logging_configuration.side_effect = error
        else:
            client.get_model_invocation_logging_configuration.return_value = {
                "loggingConfig": config
            }
        with patch.object(bedrock_app.boto3, "client", return_value=client):
            result = bedrock_app.check_guardrail_intervention_logging(
                region=self.REGION
            )
        rows = extract_csv_data(result)
        for row in rows:
            assert_finding_schema(row)
            assert row["Check_ID"] == "BR-34"
            assert row["Finding"] == "Guardrail Intervention Logging"
        return rows

    def test_logging_off_fails(self):
        rows = self._run(config=None)
        assert [r["Status"] for r in rows] == ["Failed"]
        assert "Model invocation logging is off" in rows[0]["Finding_Details"]

    def test_both_destinations_without_text_delivery_fail(self):
        rows = self._run(
            config={
                "s3Config": {"bucketName": "logs-a"},
                "cloudWatchConfig": {"logGroupName": "lg-b"},
                "textDataDeliveryEnabled": False,
                "imageDataDeliveryEnabled": True,
            }
        )
        assert [r["Status"] for r in rows] == ["Failed"]
        assert "S3 bucket 'logs-a' and log group 'lg-b'" in rows[0]["Finding_Details"]
        assert "textDataDeliveryEnabled not true" in rows[0]["Finding_Details"]

    def test_a_destination_without_the_text_flag_is_not_credited(self):
        rows = self._run(config={"cloudWatchConfig": {"logGroupName": "lg-b"}})
        assert [r["Status"] for r in rows] == ["N/A"]
        assert "did not return textDataDeliveryEnabled" in rows[0]["Finding_Details"]

    def test_text_delivery_to_a_destination_passes_and_names_it(self):
        rows = self._run(
            config={
                "s3Config": {"bucketName": "logs-a"},
                "textDataDeliveryEnabled": True,
            }
        )
        assert [r["Status"] for r in rows] == ["Passed"]
        details = rows[0]["Finding_Details"]
        assert "S3 bucket 'logs-a'" in details
        assert "judged by BR-41 and BR-49, not here" in details

    def test_unread_configuration_is_na_naming_the_action(self):
        rows = self._run(error=_make_client_error("AccessDeniedException"))
        assert [r["Status"] for r in rows] == ["N/A"]
        assert (
            "bedrock:GetModelInvocationLoggingConfiguration was not read"
            in rows[0]["Finding_Details"]
        )


class TestGuardrailConditionPins:
    """The deployed-guardrail population includes guardrails callers are made to name."""

    REGION = "us-east-1"
    PINNED = "arn:aws:bedrock:us-east-1:123456789012:guardrail/gr-9"

    @staticmethod
    def _scps(*statements, management=False):
        return {
            "items": [
                {
                    "name": "guard",
                    "id": "p-1",
                    "content": json.dumps(
                        {"Version": "2012-10-17", "Statement": list(statements)}
                    ),
                    "attached_to": ["root r-1"],
                }
            ],
            "errors": [],
            "list_error": None,
            "detached": [],
            "account": "123456789012",
            "path": [],
            "management_account": management,
        }

    def _run(self, cache, scps=None, effective=None, versions=None, in_use=True):
        agent_client = MagicMock()
        agent_client.list_agents.return_value = {"agentSummaries": []}
        agent_client.list_flows.return_value = {"flowSummaries": []}
        bedrock_client = MagicMock()
        bedrock_client.list_enforced_guardrails_configuration.return_value = {
            "guardrailsConfig": []
        }
        bedrock_client.list_guardrails.return_value = {
            "guardrails": [{"id": "gr-9", "version": v} for v in versions or []]
        }
        bedrock_client.get_guardrail.side_effect = lambda **kwargs: {
            "guardrail": dict(kwargs)
        }
        orgs_client = MagicMock()
        if effective is None:
            orgs_client.describe_effective_policy.side_effect = ClientError(
                {"Error": {"Code": "EffectivePolicyNotFoundException", "Message": "x"}},
                "DescribeEffectivePolicy",
            )
        else:
            orgs_client.describe_effective_policy.return_value = {
                "EffectivePolicy": {"PolicyContent": json.dumps(effective)}
            }
        clients = {
            "bedrock-agent": agent_client,
            "bedrock": bedrock_client,
            "organizations": orgs_client,
        }
        with (
            patch(
                "bedrock_app.boto3.client",
                side_effect=lambda service, **_: clients[service],
            ),
            patch(
                "bedrock_app._organization_policy_context",
                return_value={"in_use": in_use},
            ),
        ):
            return bedrock_app.get_guardrail_attachment_inventory(
                self.REGION,
                permission_cache=cache,
                scp_inventory=scps if scps is not None else self._scps(),
            )

    def test_an_iam_condition_pin_joins_the_population(self):
        cache = _br10_cache(
            roles={
                "Pinned": _br10_identity(_br10_bound(f"{self.PINNED}:3")),
                "Open": _br10_identity(_br10_allow()),
            },
            errors=[],
        )
        inventory = self._run(cache)
        assert list(inventory["versions"]) == [(self.PINNED, "3")]
        assert inventory["versions"][(self.PINNED, "3")]["surfaces"] == [
            "a bedrock:GuardrailIdentifier condition on role 'Pinned'"
        ]
        assert inventory["errors"] == []

    def test_a_group_policy_pin_joins_the_population(self):
        group = {
            "group": "invokers",
            "name": "G",
            "arn": "arn:aws:iam::123456789012:policy/G",
            "document": {
                "Version": "2012-10-17",
                "Statement": [_br10_bound(f"{self.PINNED}:4")],
            },
        }
        cache = _br10_cache(
            users={"alice": _br10_identity(_br10_allow(), groups=[group])}, errors=[]
        )
        inventory = self._run(cache)
        assert (self.PINNED, "4") in inventory["versions"]

    def test_an_unversioned_pin_reads_every_version(self):
        cache = _br10_cache(
            roles={"Pinned": _br10_identity(_br10_bound(self.PINNED))}, errors=[]
        )
        inventory = self._run(cache, versions=["1", "2"])
        assert sorted(inventory["versions"]) == [
            (self.PINNED, "1"),
            (self.PINNED, "2"),
            (self.PINNED, "DRAFT"),
        ]

    def test_a_wildcard_pin_is_reported_and_not_enumerated(self):
        cache = _br10_cache(
            roles={
                "Pattern": _br10_identity(
                    _br10_bound(
                        "arn:aws:bedrock:us-east-1:123456789012:guardrail/*",
                        "StringLike",
                    )
                ),
                "Pinned": _br10_identity(_br10_bound(f"{self.PINNED}:3")),
            },
            errors=[],
        )
        inventory = self._run(cache)
        assert list(inventory["versions"]) == [(self.PINNED, "3")]
        assert len(inventory["errors"]) == 1
        assert "role 'Pattern'" in inventory["errors"][0]
        assert "were not enumerated" in inventory["errors"][0]

    def test_a_pin_on_another_region_is_left_to_that_region(self):
        cache = _br10_cache(
            roles={
                "West": _br10_identity(
                    _br10_bound(
                        "arn:aws:bedrock:us-west-2:123456789012:guardrail/gr-2:1"
                    )
                )
            },
            errors=[],
        )
        assert self._run(cache)["versions"] == {}

    def test_a_pin_on_an_errored_cache_is_not_a_complete_population(self):
        cache = _br10_cache(
            roles={"Pinned": _br10_identity(_br10_bound(f"{self.PINNED}:3"))},
            errors=[
                {
                    "type": "role",
                    "name": "Other",
                    "stage": "inline_policy",
                    "error": "x",
                }
            ],
        )
        inventory = self._run(cache)
        assert (self.PINNED, "3") in inventory["versions"]
        assert any("were not searched" in error for error in inventory["errors"])

    def test_a_version_one_cache_says_errors_were_not_recorded(self):
        cache = _br10_cache(roles={})
        inventory = self._run(cache)
        assert any("version 1" in error for error in inventory["errors"])

    def test_an_scp_pin_joins_in_a_member_account_only(self):
        deny = {
            "Effect": "Deny",
            "Action": _INVOKE_BOTH,
            "Resource": "*",
            "Condition": {"StringNotEquals": {"bedrock:GuardrailIdentifier": "gr-7:2"}},
        }
        cache = _br10_cache(errors=[])
        member = self._run(cache, scps=self._scps(deny))
        assert member["versions"][("gr-7", "2")]["surfaces"] == [
            "a bedrock:GuardrailIdentifier condition in service control policy 'guard'"
        ]
        assert (
            self._run(cache, scps=self._scps(deny, management=True))["versions"] == {}
        )

    def test_the_effective_bedrock_policy_joins_only_its_region(self):
        effective = {
            "bedrock": {
                "guardrail_inference": {
                    region: {"baseline": {"identifier": f"{guardrail}:{version}"}}
                    for region, guardrail, version in (
                        ("us-east-1", self.PINNED, "5"),
                        (
                            "eu-west-1",
                            "arn:aws:bedrock:eu-west-1:123456789012:guardrail/gr-3",
                            "1",
                        ),
                    )
                }
            }
        }
        inventory = self._run(_br10_cache(errors=[]), effective=effective)
        assert list(inventory["versions"]) == [(self.PINNED, "5")]

    def test_an_unreadable_effective_policy_is_an_error(self):
        cache = _br10_cache(errors=[])
        agent_client = MagicMock()
        with (
            patch(
                "bedrock_app._organization_policy_context",
                return_value={"in_use": True},
            ),
            patch("bedrock_app.boto3.client") as client,
        ):
            client.return_value = agent_client
            agent_client.list_agents.return_value = {"agentSummaries": []}
            agent_client.list_flows.return_value = {"flowSummaries": []}
            agent_client.list_enforced_guardrails_configuration.return_value = {
                "guardrailsConfig": []
            }
            agent_client.describe_effective_policy.side_effect = ClientError(
                {"Error": {"Code": "AccessDeniedException", "Message": "x"}},
                "DescribeEffectivePolicy",
            )
            inventory = bedrock_app.get_guardrail_attachment_inventory(
                self.REGION, permission_cache=cache, scp_inventory=self._scps()
            )
        assert any("effective Bedrock policy" in error for error in inventory["errors"])

    def test_a_pinned_version_that_fails_the_judge_fails_the_check(self):
        cache = _br10_cache(
            roles={"Pinned": _br10_identity(_br10_bound(f"{self.PINNED}:3"))},
            errors=[],
        )
        inventory = self._run(cache)
        rows = bedrock_app._deployed_guardrail_findings(
            "BR-26",
            "Deployed",
            bedrock_app.GUARDRAIL_IAM_REFERENCE,
            self.REGION,
            inventory,
            lambda detail: ("Failed", "no filter"),
            "fix",
            "High",
        )
        assert [row["Status"] for row in rows] == ["Failed"]
        assert "condition on role 'Pinned'" in rows[0]["Finding_Details"]


class TestDeployedGuardrailEnforcedNarrowings:
    """A narrowed account-enforced configuration does not credit its guardrail."""

    REGION = "us-east-1"
    ARN = "arn:aws:bedrock:us-east-1:123456789012:guardrail/"

    def _inventory(self, configs):
        agent_client = MagicMock()
        agent_client.list_agents.return_value = {"agentSummaries": []}
        agent_client.list_flows.return_value = {"flowSummaries": []}
        bedrock_client = MagicMock()
        bedrock_client.list_enforced_guardrails_configuration.return_value = {
            "guardrailsConfig": configs
        }
        bedrock_client.get_guardrail.side_effect = lambda **kwargs: {
            "guardrail": dict(kwargs)
        }
        clients = {"bedrock-agent": agent_client, "bedrock": bedrock_client}
        with patch(
            "bedrock_app.boto3.client",
            side_effect=lambda service, **_: clients[service],
        ):
            return bedrock_app.get_guardrail_attachment_inventory(self.REGION)

    def _config(self, config_id, guardrail, **extra):
        return {
            "configId": config_id,
            "guardrailArn": self.ARN + guardrail,
            "guardrailVersion": "1",
            **extra,
        }

    def _rows(self, configs):
        return bedrock_app._deployed_guardrail_findings(
            "BR-34",
            "Deployed",
            bedrock_app.GUARDRAIL_IAM_REFERENCE,
            self.REGION,
            self._inventory(configs),
            lambda detail: ("Passed", "filter set"),
            "fix",
            "High",
        )

    def test_selective_messages_guarding_is_not_credited(self):
        rows = self._rows(
            [
                self._config(
                    "c-1", "gr-a", selectiveContentGuarding={"messages": "SELECTIVE"}
                )
            ]
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        details = rows[0]["Finding_Details"]
        assert "account-enforced configuration c-1 applies it only in part" in details
        assert "messages content is guarded SELECTIVE" in details
        assert "pass:" not in details

    def test_one_honor_config_fails_beside_a_comprehensive_one(self):
        rows = self._rows(
            [
                self._config("c-full", "gr-a"),
                self._config("c-tags", "gr-b", inputTags="HONOR"),
            ]
        )

        assert sorted(row["Status"] for row in rows) == ["Failed", "Passed"]
        failed = next(row for row in rows if row["Status"] == "Failed")
        passed = next(row for row in rows if row["Status"] == "Passed")
        assert "account-enforced configuration c-tags" in failed["Finding_Details"]
        assert "inputTags is HONOR" in failed["Finding_Details"]
        assert "gr-a version 1" in passed["Finding_Details"]
        assert "gr-b" not in passed["Finding_Details"]

    def test_a_narrowed_surface_is_dropped_from_a_shared_version(self):
        rows = self._rows(
            [
                self._config("c-full", "gr-a"),
                self._config(
                    "c-part",
                    "gr-a",
                    modelEnforcement={"includedModels": ["model-x"]},
                ),
            ]
        )

        assert sorted(row["Status"] for row in rows) == ["Failed", "Passed"]
        passed = next(row for row in rows if row["Status"] == "Passed")
        assert (
            "applied by account-enforced configuration c-full)"
            in (passed["Finding_Details"])
        )
        assert "c-part" not in passed["Finding_Details"]
        failed = next(row for row in rows if row["Status"] == "Failed")
        assert "includedModels does not name ALL" in failed["Finding_Details"]

    def test_a_narrowed_config_on_a_failing_guardrail_fails_once(self):
        rows = bedrock_app._deployed_guardrail_findings(
            "BR-26",
            "Deployed",
            bedrock_app.GUARDRAIL_IAM_REFERENCE,
            self.REGION,
            self._inventory([self._config("c-1", "gr-a", inputTags="HONOR")]),
            lambda detail: ("Failed", "no filter"),
            "fix",
            "High",
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "fails: no filter" in rows[0]["Finding_Details"]


