    assert "Grant" not in rows[0]["Resolution"]
    # ListMemories is granted for BR-53, so the row must not call it missing.
    assert "ListMemories" not in rows[0]["Finding_Details"]
    assert "ListMemories" not in rows[0]["Resolution"]


