        rows = self._run(
            {"kb1": self._aoss_body()},
            clients={"opensearchserverless": self._aoss("auto")},
        )
        assert [r["Status"] for r in rows] == ["Failed"]
        assert "kmsKeyArn is 'auto'" in rows[0]["Finding_Details"]

